import json, os, urllib.request, urllib.error

base = "http://service:8080"
tok = os.environ["ARTIFACT_API_TOKEN"]

def req(method, path, headers=None, body=None):
    h = {"Authorization": "Bearer " + tok}
    if headers: h.update(headers)
    data = None
    if body is not None:
        data = body if isinstance(body, bytes) else json.dumps(body).encode()
        h.setdefault("Content-Type", "application/json")
    r = urllib.request.Request(base + path, data=data, headers=h, method=method)
    try:
        with urllib.request.urlopen(r, timeout=10) as resp:
            return resp.status, dict(resp.headers), resp.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as e:
        return e.code, dict(e.headers), e.read().decode("utf-8", "replace")

# OPTIONS to learn requirements
for m in ["OPTIONS", "PUT", "PATCH"]:
    s, hh, b = req(m, "/v1/objects")
    print(f"=== {m} /v1/objects -> {s} ===")
    print("Allow:", hh.get("Allow"), "| WWW-Auth:", hh.get("WWW-Authenticate"))
    print(b[:600]); print()

# Candidate header schemes, empty body
cands = [
    {"Project": "sqlite-utils", "Version": "4.1.1", "Path": "x.whl"},
    {"X-Project": "sqlite-utils", "X-Version": "4.1.1", "X-Path": "x.whl"},
    {"X-Artifact-Project": "sqlite-utils", "X-Artifact-Version": "4.1.1", "X-Artifact-Path": "x.whl"},
    {"X-Metadata-Project": "sqlite-utils", "X-Metadata-Version": "4.1.1", "X-Metadata-Path": "x.whl"},
    {"Upload-Metadata-Project": "sqlite-utils"},
]
for c in cands:
    s, hh, b = req("POST", "/v1/objects", c, b"")
    print(f"=== POST headers={list(c)} -> {s} ===")
    print(b[:400]); print()
EOF","description":"Probe OPTIONS and try candidate metadata headers"}

