    "request_id": "probe-1",
    "idempotency_key": "probe-key-1",
    "repository": "probe-invalid-repo",
    "project": "sqlite-utils",
    "version": "4.1.1",
    "object_path": "probe.bin",
    "content_sha256": Z,
    "body_sha256": Z,
    "content_size_bytes": 4,
}

def post(headers, body=b"ABCD"):
    h = {"Authorization": "Bearer " + tok}
    h.update(headers)
    r = urllib.request.Request(base + "/v1/objects", data=body, headers=h, method="POST")
    try:
        with urllib.request.urlopen(r, timeout=10) as resp:
            return resp.status, resp.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode("utf-8", "replace")

def msg(out):
