    print(f"{name:28s} -> {s} {msg(out)}")

# incremental: one header at a time, then pairs
names = ["repository", "project", "version", "object_path", "content_sha256", "body_sha256", "content_size_bytes"]
for i, n in enumerate(names):
    hdrs = {k: str(VALS[k]) for k in names[: i + 1]}
    s, out = post(hdrs)
    print(f"first {i+1} underscore hdrs  -> {s} {msg(out)}")
